e":"Venstre underarm","type":"path","parent":"upper-left","fill":"none","geo":{"d":"M0 0 L-21 34"},"keys":[{"t":0,"x":-36,"y":34,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#168D92","strokeWidth":10,"rig":"bone"},{"id":"upper-right","name":"Højre overarm","type":"path","parent":"body","fill":"none","geo":{"d":"M0 0 L36 34"},"keys":[{"t":0,"x":2,"y":-78,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#6352AA","strokeWidth":12,"rig":"bone"},{"id":"lower-right","name":"Højre underarm","type":"path","parent":"upper-right","fill":"none","geo":{"d":"M0 0 L21 34"},"keys":[{"t":0,"x":36,"y":34,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#6352AA","strokeWidth":10,"rig":"bone"},{"id":"thigh-left","name":"Venstre lår","type":"path","parent":"body","fill":"none","geo":{"d":"M0 0 L-20 50"},"keys":[{"t":0,"x":-2,"y":0,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#223C50","strokeWidth":14,"rig":"bone"},{"id":"shin-left","name":"Venstre underben","type":"path","parent":"thigh-left","fill":"none","geo":{"d":"M0 0 L4 52"},"keys":[{"t":0,"x":-20,"y":50,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#223C50","strokeWidth":11,"rig":"bone"},{"id":"foot-left","name":"Venstre fod","type":"path","parent":"shin-left","fill":"none","geo":{"d":"M0 0 L-23 4"},"keys":[{"t":0,"x":4,"y":52,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#EE6C4D","strokeWidth":8,"rig":"bone"},{"id":"thigh-right","name":"Højre lår","type":"path","parent":"body","fill":"none","geo":{"d":"M0 0 L20 50"},"keys":[{"t":0,"x":2,"y":0,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#223C50","strokeWidth":14,"rig":"bone"},{"id":"shin-right","name":"Højre underben","type":"path","parent":"thigh-right","fill":"none","geo":{"d":"M0 0 L-4 52"},"keys":[{"t":0,"x":20,"y":50,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#223C50","strokeWidth":11,"rig":"bone"},{"id":"foot-right","name":"Højre fod","type":"path","parent":"shin-right","fill":"none","geo":{"d":"M0 0 L23 4"},"keys":[{"t":0,"x":-4,"y":52,"r":0,"sx":1,"sy":1,"opacity":1,"easing":"smooth"}],"pivot":{"x":0,"y":0},"stroke":"#EE6C4D","strokeWidth":8,"rig":"bone"}]}"},"$:/plugins/huwiki/cutout/delivery-studio.js":{"title":"$:/plugins/huwiki/cutout/delivery-studio.js","type":"application/javascript","module-type":"library","text":"var coUi=require("$:/plugins/huwiki/cutout/i18n.js");
/*\
title: $:/plugins/huwiki/cutout/delivery-studio.js
type: application/javascript
