(function(){'use strict';
var P=require('$:/plugins/huwiki/cutout/publish.js');
exports.install=function(Studio){
 var ui=Studio.prototype.ui;
 Studio.prototype.preparePublication=function(){
  if(!this.save())return;this.stop();P.ready(this.wiki,this.title);
  this.wiki.addTiddler(new $tw.Tiddler({title:'$:/CutOut/PublishDraft',type:'application/json',text:JSON.stringify({version:1,name:this.data.name,mode:'single',entries:[{id:this.data.id,title:this.title}]})}));
  this.dispatchEvent({type:'tm-navigate',navigateTo:'HUWiki CutOut – Del',navigateFromTitle:this.getVariable('currentTiddler'),navigateFromNode:this.host});
 };
 Studio.prototype.ui=function(){ui.call(this);if(!this.data||this.mode==='puppet')return;var self=this,box=this.node('section',undefined,'co-finish');
  this.node('strong',this.mode==='theatre'?coUi.t('Afslut forestillingen · Kamera → Afprøv → Del'):coUi.t('Når animationen er klar'),'',box);var actions=this.node('div',undefined,'',box);
  if(this.mode==='theatre'){
   this.button(actions,coUi.t('1. Kamera og udsnit'),function(){self.selectCamera();});
   this.button(actions,coUi.t('2. Afprøv hele stykket'),function(){self.stop();self.time=0;self.cameraPreview=true;self.ui();self.stage.scrollIntoView({block:'center'});});
  }
  this.button(actions,this.mode==='theatre'?coUi.t('3. Gør klar til deling'):coUi.t('Gør klar til deling'),function(){self.preparePublication();});
  this.node('p',this.mode==='theatre'?coUi.t('Kameraet bestemmer publikums udsnit. Uden kameranøglebilleder vises hele scenen. Deling åbner med netop denne forestilling valgt.'):coUi.t('Del animationen alene, i en rækkefølge eller på en side med tekst.'),'co-hint',box);
  var layout=this.host.querySelector('.co-layout');layout.before(box);
 };
};
})();
"},"$:/plugins/huwiki/cutout/clock.js":{"title":"$:/plugins/huwiki/cutout/clock.js","type":"application/javascript","module-type":"library","text":"/*\
title: $:/plugins/huwiki/cutout/clock.js
type: application/javascript
module-type: library
\*/
(function(){'use strict';
function Clock(options){this.o=options;this.time=0;this.playing=false;this.frame=0;this.last=null;}
Clock.prototype.pause=function(){this.playing=false;if(this.frame)this.o.cancel(this.frame);this.frame=0;this.last=null;if(this.o.status)this.o.status(false);};
Clock.prototype.seek=function(t){this.time=Math.max(0,Math.min(this.o.duration,Number(t)||0));this.o.paint(this.time);};
Clock.prototype.play=function(){if(this.playing)return;var self=this;if(this.time>=this.o.duration)this.seek(0);this.playing=true;this.last=null;if(this.o.status)this.o.status(true);function tick(now){self.frame=0;if(!self.playing)return;if(self.o.alive&&!self.o.alive()){self.pause();return;}var next=self.time+(self.last===null?0:(now-self.last)/1000);self.last=now;if(next>=self.o.duration){if(self.o.loop)self.seek(next%self.o.duration);else{self.seek(self.o.duration);self.pause();return;}}else self.seek(next);self.frame=self.o.request(tick);}this.frame=this.o.request(tick);};
Clock.prototype.destroy=function(){this.pause();};exports.Clock=Clock;
})();
"},"HUWiki CutOut – Del":{"title":"HUWiki CutOut – Del","type":"text/vnd.tiddlywiki","text":"<$cutout-language-page/>
","cutout-ui-title-en":"CutOut – Share","forge-display-name":"CutOut – Del","caption":"CutOut – Del"},"$:/plugins/huwiki/cutout/publication.css":{"title":"$:/plugins/huwiki/cutout/publication.css","type":"text/css","tags":"$:/tags/Stylesheet","text":".co-published{font:16px/1.5 system-ui,sans-serif;max-width:1200px;margin:auto;padding:20px;color:#213b38}.co-published>h1{font-size:clamp(22px,4vw,34px);margin:0 0 18px}.co-published>section{background:white;padding:10px;border-radius:10px}.co-published nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.co-published button,.co-publisher button,.co-publisher select,.co-publisher input{font:inherit;min-height:42px;padding:8px 12px;border:1px solid #b7cabc;border-radius:8px;background:white;color:#213b38}.co-published button,.co-publisher button{cursor:pointer}.co-published button[aria-current=page]{background:#285947;color:white}.co-published>.co-status,.co-published>p{font-size:13px;color:#52685b}.co-published .huw-cutout-player{border:1px solid #ccd9ce;border-radius:8px;overflow:hidden}.co-published .huw-cutout-player>svg{display:block;width:100%;max-height:75dvh}.co-published .huw-cutout-controls{padding:10px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;background:#eff4ed}.co-published .huw-cutout-controls>input{min-width:100px;flex:1}.co-published .huw-cutout-controls span{font-size:13px}.co-published .huw-cutout-controls button{font-size:13px}.co-published [hidden]{display:none!important}
