"},"$:/plugins/huwiki/cutout/camera-studio.js":{"title":"$:/plugins/huwiki/cutout/camera-studio.js","type":"application/javascript","module-type":"library","text":"var coUi=require("$:/plugins/huwiki/cutout/i18n.js");
/*\
title: $:/plugins/huwiki/cutout/camera-studio.js
type: application/javascript
module-type: library
\*/
(function(){'use strict';
var E=require('$:/plugins/huwiki/cutout/engine.js'),V=require('$:/plugins/huwiki/cutout/viewport.js'),NS='http://www.w3.org/2000/svg';
exports.install=function(Studio){
 Studio.prototype.cameraKey=function(){
  var d=this.data,t=this.time,state=E.cameraState(d,t);
  if(!d.camera)d.camera={keys:[{t:0,x:d.width/2,y:d.height/2,zoom:1,easing:'smooth'}]};
  var key=d.camera.keys.find(function(k){return Math.abs(k.t-t)<.0001;});
  if(!key){key=Object.assign({t:t,easing:'smooth'},state);d.camera.keys.push(key);d.camera.keys.sort(function(a,b){return a.t-b.t;});}
  return key;
 };
 Studio.prototype.setCamera=function(values){
  var key=this.cameraKey();['x','y','zoom'].forEach(function(p){if(values[p]!==undefined)key[p]=p==='zoom'?E.clamp(Number(values[p]),.25,16):Number(values[p]);});
  this.mark();this.paint();
 };
 Studio.prototype.selectCamera=function(){this.stop();this.selected='@camera';this.cameraPreview=false;this.ui();};
 Studio.prototype.cameraControls=function(center,right){
  var self=this,state=E.cameraState(this.data,this.time),bar=this.node('div',undefined,'co-camera-controls');center.insertBefore(bar,this.stage);
  this.node('strong',coUi.t('Kamera · fælles udsnit ved ')+this.time.toFixed(2)+' s','',bar);
  this.node('p',coUi.t('Træk rammen for at flytte kameraet. Træk et hjørne for at beskære og zoome. Udsnittet har forestillingens format.'),'co-hint',bar);
  var arrows=this.node('div',undefined,'co-object-move',bar);
  [['←',coUi.t('venstre'),-1,0],['↑',coUi.t('op'),0,-1],['↓',coUi.t('ned'),0,1],['→',coUi.t('højre'),1,0]].forEach(function(a){var b=self.button(arrows,a[0],function(){var s=E.cameraState(self.data,self.time),step=self.cameraStep||10;self.setCamera({x:s.x+a[2]*step,y:s.y+a[3]*step});self.ui();});b.setAttribute('aria-label',coUi.t('Flyt kamera ')+a[1]);});
  this.choice(bar,coUi.t('Kameratrin'),String(this.cameraStep||10),[{id:'1',name:coUi.t('Fint · 1')},{id:'10',name:'Normal · 10'},{id:'50',name:coUi.t('Groft · 50')}],function(v){self.cameraStep=Number(v);});
  this.button(bar,coUi.t('Kamera nærmere +'),function(){self.setCamera({zoom:E.cameraState(self.data,self.time).zoom*1.25});self.ui();});
  this.button(bar,coUi.t('Kamera længere væk −'),function(){self.setCamera({zoom:E.cameraState(self.data,self.time).zoom/1.25});self.ui();});
  this.button(bar,coUi.t('Vis hele kamerarammen'),function(){self.camera=V.fit(self.data.width,self.data.height,E.cameraBox(self.data,self.time),self.viewAspect());self.paintViewport();});
  this.button(bar,coUi.t('Hele forestillingen her'),function(){self.setCamera({x:self.data.width/2,y:self.data.height/2,zoom:1});self.ui();});
  this.button(bar,coUi.t('◆ Kamerapunkt her'),function(){self.cameraKey();self.mark();self.ui();});
  this.button(bar,this.cameraPreview?coUi.t('Tilbage til kamerarammen'):coUi.t('Afprøv kameraturen'),function(){self.cameraPreview=!self.cameraPreview;self.ui();});
  this.cameraOutput=this.node('output',undefined,'co-camera-output',bar);
  this.node('h3',coUi.t('Kameraets nøglebilleder'),'',right);
  this.node('p',coUi.t('Punkterne bruger hele forestillingens tid og fortsætter gennem sceneskift. Arbejdszoom og kamerazoom er to forskellige kontroller.'),'co-hint',right);
  var exact=this.node('details',undefined,'co-exact',right);this.node('summary',coUi.t('Præcist kamera'),'',exact);
  [['x',coUi.t('Kameramidte X')],['y',coUi.t('Kameramidte Y')]].forEach(function(a){self.field(exact,a[1],state[a[0]],'number',function(v){var values={};values[a[0]]=v;self.setCamera(values);self.ui();});});
  this.field(exact,coUi.t('Kamerazoom (%)'),state.zoom*100,'number',function(v){self.setCamera({zoom:v/100});self.ui();});
  var track=this.data.camera,at=track&&this.keyAt(track);
  this.choice(right,coUi.t('Kameraovergang'),at&&at.easing||'smooth',[{id:'smooth',name:coUi.t('Blød')},{id:'linear',name:coUi.t('Lineær')},{id:'step',name:coUi.t('Øjeblikkelig')}],function(v){self.cameraKey().easing=v;self.mark();self.ui();});
  (track&&track.keys||[]).forEach(function(k){var row=self.node('div',undefined,'co-key',right);self.button(row,coUi.t('◆ Kamera ')+k.t.toFixed(2)+' s',function(){self.time=E.clamp(k.t,0,self.data.duration);self.ui();});self.field(row,coUi.t('Kamerapunktets tid'),k.t,'number',function(v){if(v<0||v>self.data.duration||track.keys.some(function(q){return q!==k&&Math.abs(q.t-v)<.0001;})){self.message(coUi.t('Vælg en ledig tid i forestillingen'));return;}k.t=v;track.keys.sort(function(a,b){return a.t-b.t;});self.time=v;self.mark();self.ui();});});
  var remove=this.button(right,coUi.t('Fjern kameranøglebillede'),function(){track.keys=track.keys.filter(function(k){return Math.abs(k.t-self.time)>.0001;});self.mark();self.ui();});remove.disabled=!at||track.keys.length<=1;
  var clear=this.button(right,coUi.t('Fjern kameraspor'),function(){delete self.data.camera;self.mark();self.ui();});clear.disabled=!track;
 };
 Studio.prototype.cameraKeyStrip=function(center){
  var self=this,strip=this.node('div',undefined,'co-key-strip co-camera-keys',center);
  this.node('strong',coUi.t('Nøglebilleder · Kamera'),'',strip);
  (this.data.camera&&this.data.camera.keys||[]).forEach(function(k){var b=self.button(strip,'◆ '+k.t.toFixed(2)+' s',function(){self.time=E.clamp(k.t,0,self.data.duration);self.ui();});b.dataset.keyTime=String(k.t);});
  this.button(strip,coUi.t('◆ Tilføj her'),function(){self.cameraKey();self.mark();self.ui();});
 };
 Studio.prototype.paintCameraFrame=function(){
  var existing=this.view.svg.querySelector('.co-camera-frame');
