exports.context=function(){return {connected:false};};
exports.exportHtml=async function(wiki,output,name,doc){P.downloadBlob(P.archiveHtml(output,name),name,doc);return {downloaded:true};};
exports.result=function(parent){parent.textContent=coUi.t('ZIP hentet · Pak ud og åbn index.html.');};
async function readPackage(file){
 if(file.size>20*1024*1024)throw Error(coUi.t('Vælg en CutOut ZIP under 20 MB.'));var Zip=require('$:/plugins/huwiki/cutout/vendor/jszip.js'),zip=new Zip(await file.arrayBuffer()),names=Object.keys(zip.files);
 if(names.some(function(n){return n!=='index.html'&&n!=='LAES-MIG.txt';})||!zip.file('index.html'))throw Error(coUi.t('Vælg en CutOut-udgivelse med index.html.'));var item=zip.file('index.html');if(item._data&&item._data.uncompressedSize>30*1024*1024)throw Error(coUi.t('HTML-filen er for stor.'));
 var output=item.asText();if(output.length>30*1024*1024||output.indexOf('<meta name="huwiki-cutout-site" content="1">')<0)throw Error(coUi.t('Pakken er ikke en CutOut-udgivelse.'));
 var match=output.match(/<script class="tiddlywiki-tiddler-store" type="application\/json">([\s\S]*?)<\/script>/),rows=match&&JSON.parse(match[1]),config=rows&&rows.find(function(t){return t.title==='$:/CutOut/Publication';});if(!config)throw Error(coUi.t('Pakken mangler sin afspilningsopsætning.'));config=JSON.parse(config.text);return {html:output,name:config.name||file.name.replace(/\.zip$/i,''),items:config.items};
}
exports.readPackage=readPackage;

