(function(){'use strict';
var M=require('$:/plugins/huwiki/cutout/model.js'),E=require('$:/plugins/huwiki/cutout/engine.js');
var names=coUi.names({puppet:'Dukkeværksted',animation:'Animationsstudie',scene:'Scenestudie',theatre:'Teaterstudie'});
function group(title){return title.indexOf('Øvelse · ')===0?title.split(' / ')[0]:'';}
exports.install=function(Studio){
 var originalUI=Studio.prototype.ui,originalPaint=Studio.prototype.paint;
 Studio.prototype.library=function(kind){
  var current=group(this.title||'');
  return M.list(this.wiki,kind).filter(function(item){var g=group(item.title);return !g||g===current;});
 };
 Studio.prototype.context=function(){return {title:this.title,mode:this.mode,time:this.time,selected:this.selected,camera:this.camera,cameraPreview:this.cameraPreview,name:this.data&&this.data.name,history:(this.history||[]).slice()};};
 Studio.prototype.restoreContext=function(c){this.mode=c.mode;this.history=(c.history||[]).slice();if(c.title){this.load(c.title);this.selected=c.selected;this.camera=c.camera;this.cameraPreview=c.cameraPreview;this.time=E.clamp(c.time||0,0,this.data.duration);}else{this.data=null;this.title='';this.time=0;}this.ui();};
 Studio.prototype.switchWorkspace=function(mode){
  if(mode===this.mode)return;
  this.sessions=this.sessions||{};this.draft();this.sessions[this.mode]=this.context();
  this.restoreContext(this.sessions[mode]||{mode:mode,title:''});
 };
 Studio.prototype.goAncestor=function(index){
  var path=this.history||[],target=path[index];if(!target)return;
  var self=this,pending=path.slice(index+1).map(function(c){return {context:c,data:M.read(self.wiki,'$:/CutOut/Drafts/'+c.title)};}).filter(function(x){return x.data;});
  var invalid=pending.find(function(x){return M.validate(x.data).length;});
  if(invalid){this.message(coUi.t('Ret fejl i ')+invalid.context.name+coUi.t(' før du går tilbage.'));return;}
  if(!this.save())return;
  pending.forEach(function(x){M.write(self.wiki,x.context.title,x.data,x.context.mode);self.wiki.deleteTiddler('$:/CutOut/Drafts/'+x.context.title);});
  target=Object.assign({},target,{history:path.slice(0,index)});this.restoreContext(target);
  this.host.querySelector('.co-location').scrollIntoView({block:'start'});
 };
 Studio.prototype.disclosure=function(parent,label,key){
  var self=this,d=this.node('details',undefined,'co-disclosure',parent);
  this.node('summary',label,'',d);this.openSections=this.openSections||{};
  d.open=!!this.openSections[key];d.ontoggle=function(){if(d.isConnected)self.openSections[key]=d.open;};return d;
 };
 Studio.prototype.createNext=function(){
  if(!this.save())return;
  var mode={puppet:'animation',animation:'scene',scene:'theatre'}[this.mode];if(!mode)return;
  var source=this.data,sourceTitle=this.title,next=this.project(mode);
  next.name=source.name+' · '+{animation:'animation',scene:'scene',theatre:'forestilling'}[mode];
  next.width=source.width;next.height=source.height;next.duration=source.duration;
  if(mode==='animation'){
   next.parts=M.instantiate(source);next.parts.forEach(function(p){if(p.type==='image'){p.imageData=E.imageHref(this.wiki,p);(p.variants||[]).forEach(function(v){v.imageData=E.imageHref(this.wiki,v);},this);}},this);
  }else if(mode==='scene')next.parts=[{id:M.id('clip'),name:source.name,type:'animation',animationId:source.id,animation:sourceTitle,start:0,offset:0,speed:1,loop:false,geo:{x:0,y:0,w:source.width,h:source.height},keys:[{t:0,x:0,y:0,r:0,sx:1,sy:1,opacity:1}]}];
  else next.scenes=[{id:M.id('scene'),name:source.name,sourceId:source.id,source:sourceTitle,duration:source.duration,speed:1,offset:0,loop:false}];
  this.sessions=this.sessions||{};this.sessions[this.mode]=this.context();
