  ['$:/plugins/huwiki/slideshow','$:/plugins/huwiki/pasteup'].forEach(function(n){var t=wiki.getTiddler(n);if(!t)throw Error(coUi.t('Installér HUWiki Slideshow og PasteUp for at danne et Slideshow-site. Sider og automatisk rækkefølge virker med CutOut alene.'));if(n==='$:/plugins/huwiki/slideshow'){var clean=Object.assign({},t.fields),content=JSON.parse(clean.text);Object.keys(content.tiddlers).forEach(function(k){if(content.tiddlers[k]['huwiki-example-resource']==='yes')delete content.tiddlers[k];});clean.text=JSON.stringify(content);output.addTiddler(new $tw.Tiddler(clean));}else output.addTiddler(t);});
  var slides=items.map(function(i,n){if(!i.project)return {title:i.title,notes:'',displayMode:'standard'};var name='$:/CutOut/PublishedSlide/'+n;output.addTiddler(new $tw.Tiddler({title:name,text:'<$cutout-film tiddler="'+$tw.utils.htmlEncode(i.title)+'" loop="no" autoplay="yes"/>'}));return {title:name,notes:'',displayMode:'standard'};});
  pub.deck='$:/CutOut/PublishedDeck';output.addTiddler(new $tw.Tiddler({title:pub.deck,type:'application/json',tags:['HUWiki-Præsentation'],list:slides.map(function(s){return s.title;}),text:JSON.stringify({schema:3,name:title,theme:'night',source:{mode:'manual',value:''},slides:slides})}));
 }
 output.addTiddlers([{title:CONFIG,type:'application/json',text:JSON.stringify(pub)},{title:'$:/core/ui/PageTemplate',text:'<$cutout-published/>'},{title:'$:/DefaultTiddlers',text:''},{title:'$:/SiteTitle',text:title},{title:'$:/SiteSubtitle',text:'CutOut · afspilning'},{title:'$:/config/AutoSave',text:'no'}]);
 output.addTiddler(new $tw.Tiddler({title:'$:/CutOut/PlaybackOnly',type:'application/javascript','module-type':'startup',text:"exports.name='cutout-playback-only';exports.platforms=['browser'];exports.after=['huwiki-slideshow-startup'];exports.synchronous=true;exports.startup=function(){['tm-edit-tiddler','tm-new-tiddler','tm-save-wiki','tm-huwiki-slideshow-open'].forEach(function(type){$tw.rootWidget.addEventListener(type,function(){return false;});});};"}));
 // Only a playback interface: no CutOut editor, drawing engine, authoring library or sync plugin.
 output.readPluginInfo();output.registerPluginTiddlers('plugin');output.unpackPluginTiddlers();
 var result=output.renderTiddler('text/plain','$:/core/save/all',{variables:{wikiTitle:title,publishFilter:''}});
 if(result.indexOf('$:/boot/boot.js')<0)throw Error(coUi.t('HTML-filen kunne ikke dannes.'));return result.replace('<head>','<head><meta name="huwiki-interactive-site" content="slideshow-v1"><meta name="huwiki-cutout-site" content="1">');
}
// The same self-contained playback HTML as preview, wrapped in an ordinary ZIP.
function archiveHtml(output,name){
 var Zip=require('$:/plugins/huwiki/cutout/vendor/jszip.js'),zip=new Zip();
 zip.file('index.html',output);
 zip.file('LAES-MIG.txt','HUWiki CutOut · '+(name||'Animation')+coUi.t('\n\nPak hele ZIP-filen ud, og åbn index.html i din browser.\nAnimationer, kamerabevægelser, billeder og afspilningsmotor er indlejret i HTML-filen.\nDer er derfor ingen ekstra filmappe, der skal flyttes med.\n\nDette er en visningskopi. Gem den redigerbare wiki separat.\nSenere ændringer kræver en ny eksport.\nVil du lægge visningen på en webserver, skal index.html serveres som en hel HTML-side.\nAt åbne index.html publicerer ikke noget. Brug Udgiv som site i CutOut for at publicere gennem HUWiki.\n'));
 return zip.generate({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});
}
function archive(wiki,settings){return archiveHtml(html(wiki,settings),settings.name);}
function downloadBlob(blob,name,doc){
 var a=doc.createElement('a'),url=URL.createObjectURL(blob);
 a.href=url;a.download=String(name||'CutOut').replace(/[\\/:*?"<>|]/g,'-')+'.zip';a.click();setTimeout(function(){URL.revokeObjectURL(url);},1000);
}
function downloadArchive(wiki,settings,doc){downloadBlob(archive(wiki,settings),settings.name,doc);}
exports.archiveHtml=archiveHtml;exports.downloadBlob=downloadBlob;exports.archive=archive;exports.downloadArchive=downloadArchive;
exports.catalog=catalog;exports.ready=ready;exports.collect=collect;exports.html=html;exports.resolve=resolve;
})();
"},"$:/plugins/huwiki/cutout/legacy.css":{"title":"$:/plugins/huwiki/cutout/legacy.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/*\
title: $:/plugins/huwiki/cutout/styles.css
type: text/css
\*/
.huw-cutout-player{width:100%;max-width:100%;border-radius:12px;overflow:hidden;background:#f9fafb;box-sizing:border-box}
.huw-cutout-svg{display:block;width:100%;height:auto;aspect-ratio:16/9;touch-action:pan-y}
.huw-cutout-controls{display:flex;gap:.6em;align-items:center;padding:.65em;background:#f0f2f6;color:#313a46;font:500 .85em system-ui,sans-serif}
.huw-cutout-toggle,.huw-cutout-button{border:1px solid #ccd1db;background:#fff;color:#283745;padding:.45em .75em;border-radius:.45em;cursor:pointer;white-space:nowrap}
.huw-cutout-range,.huw-cutout-scrub{flex:1;min-width:45px;accent-color:#586eaf}
.huw-cutout-clock{font:500 .85em system-ui,sans-serif;font-variant-numeric:tabular-nums;white-space:nowrap}
.huw-cutout-error{padding:1em;display:block;color:#9c3636}
.huw-cutout-editor{font:400 14px/1.4 system-ui,sans-serif;color:#263548;background:#f7f8fa;border:1px solid #cdd5e0;border-radius:12px;overflow:hidden;margin:1em 0}
.huw-cutout-editbar,.huw-cutout-tools,.huw-cutout-timelinebar{display:flex;gap:.45em;flex-wrap:wrap;align-items:center;padding:.65em .85em;border-bottom:1px solid #d7dce5}
.huw-cutout-editbar strong{margin-right:auto}.huw-cutout-status{font-size:.85em;color:#607085;margin-right:1em}
.huw-cutout-stage{max-width:900px;margin:12px auto;background:#fff;touch-action:none;cursor:move;user-select:none}
.huw-cutout-selected > :first-child{filter:drop-shadow(0 0 5px rgba(30,95,204,.9))}
.huw-cutout-timelinebar{background:#f2f4f8}.huw-cutout-autokey{font-size:.82em;white-space:nowrap}
.huw-cutout-workspace{display:grid;grid-template-columns:minmax(0,2fr) minmax(200px,1fr);min-height:210px}
.huw-cutout-tracks,.huw-cutout-properties{padding:12px;min-width:0}.huw-cutout-tracks{border-right:1px solid #dee2e9;overflow-x:auto}
.huw-cutout-track{display:flex;align-items:center;gap:.7em;border-bottom:1px solid #ecedf1;min-height:34px}
.huw-cutout-track-label{border:0;background:transparent;flex:0 0 115px;min-width:0;overflow:hidden;text-overflow:ellipsis;text-align:left;cursor:pointer;font-size:.82em}
.huw-cutout-active{background:#e6edfb}.huw-cutout-rail{height:22px;background:repeating-linear-gradient(90deg,transparent,transparent calc(25% - 1px),#d9deeb calc(25% - 1px),#d9deeb 25%);position:relative;flex:1;min-width:100px}
.huw-cutout-diamond{position:absolute;top:0;transform:translateX(-50%);border:0;color:#3b5fbd;font-size:16px;background:transparent;cursor:pointer;padding:0}
.huw-cutout-fieldname{font-weight:650;margin:7px 0}.huw-cutout-property{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:4px 0;font-size:.86em}
.huw-cutout-property input,.huw-cutout-property select{width:105px;box-sizing:border-box;border:1px solid #cdd4df;border-radius:5px;padding:5px;background:white;color:#283745}
.huw-cutout-tools{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin;background:#fff;gap:.35em;white-space:nowrap}
.huw-cutout-tools>.huw-cutout-button{flex:0 0 auto}
.huw-cutout-keytools{display:flex;gap:.35em;align-items:center;border-left:1px solid #cdd5e0;padding-left:.6em;margin-left:.25em;flex:0 0 auto}
.huw-cutout-button:disabled{opacity:.42;cursor:not-allowed}
.huw-cutout-stage{position:relative}
.huw-cutout-contextmenu{position:absolute;z-index:1000;display:flex;flex-direction:column;gap:3px;min-width:170px;max-width:235px;padding:7px;border:1px solid #c7d0dc;border-radius:9px;background:#fff;box-shadow:0 9px 28px rgba(30,40,65,.24);color:#253348}
.huw-cutout-contextmenu[hidden]{display:none}
.huw-cutout-contextmenu .huw-cutout-contexttitle{padding:4px 7px 6px;font-size:.85em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.huw-cutout-contextmenu button{text-align:left;border:0;background:#fff;border-radius:5px;padding:.55em .65em;font-size:.9em}
.huw-cutout-contextmenu button:not(:disabled):hover,.huw-cutout-contextmenu button:not(:disabled):focus-visible{background:#eaf0fd}
.huw-cutout-contextmenu button:disabled{color:#9fa7b1;cursor:not-allowed}
.huw-cutout-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px;margin:22px 0}
.huw-cutout-card{background:#fff;border:1px solid #e1e3e6;border-radius:14px;overflow:hidden;box-shadow:0 3px 12px rgba(0,0,0,.04)}
.huw-cutout-card-art{overflow:hidden}.huw-cutout-card-copy{padding:14px}.huw-cutout-card-copy strong{font-size:1.05em}.huw-cutout-card-copy p{font-size:.87em;color:#677387;margin:7px 0 11px}.huw-cutout-card-copy a{font-weight:600;color:#3f61a1}
@media(max-width:660px){.huw-cutout-workspace{grid-template-columns:1fr}.huw-cutout-tracks{border-right:none;border-bottom:1px solid #dee2e9}.huw-cutout-track-label{flex-basis:92px}.huw-cutout-controls{gap:.3em}}

/* Pivot-stil: ledprikker vises kun for det valgte objekt. Ingen ekstra JS under afspilning. */
.huw-cutout-joint{opacity:0;pointer-events:none;fill:#fff;stroke:#256b91;stroke-width:3;filter:drop-shadow(0 2px 4px #1237)}
.huw-cutout-part.huw-cutout-selected>.huw-cutout-joint{opacity:1;pointer-events:all;cursor:grab}
.huw-cutout-part[data-cutout-id] { cursor:pointer; }
.huw-cutout-editor .huw-cutout-stage {touch-action:none;}
.huw-cutout-context-bg{display:flex;flex-direction:column;gap:3px}
.huw-cutout-context-bg[hidden]{display:none}
.huw-cutout-hint{font-size:.83em;color:#607080;background:#e8f2fa;border-radius:6px;padding:7px;}
"},"$:/plugins/huwiki/cutout/viewport.js":{"title":"$:/plugins/huwiki/cutout/viewport.js","type":"application/javascript","module-type":"library","text":"/*\
title: $:/plugins/huwiki/cutout/viewport.js
type: application/javascript
module-type: library
\*/
(function(){'use strict';
// Editor view only. Never write zoom or panning into a puppet pose/keyframe.
function finite(n,d){n=Number(n);return Number.isFinite(n)?n:d;}
function camera(width,height,c){c=c||{};return {x:finite(c.x,width/2),y:finite(c.y,height/2),zoom:Math.max(.125,Math.min(16,finite(c.zoom,1)))};}
function box(width,height,c,aspect){c=camera(width,height,c);aspect=finite(aspect,width/height);if(aspect<=0)aspect=width/height;var w=Math.max(width,height*aspect)/c.zoom,h=Math.max(height,width/aspect)/c.zoom;return {x:c.x-w/2,y:c.y-h/2,width:w,height:h};}
function reset(width,height){return camera(width,height);}
function zoom(width,height,c,factor,anchor){c=camera(width,height,c);return camera(width,height,{x:anchor?anchor.x:c.x,y:anchor?anchor.y:c.y,zoom:c.zoom*factor});}
function pan(width,height,c,dx,dy){c=camera(width,height,c);return camera(width,height,{x:c.x+finite(dx,0),y:c.y+finite(dy,0),zoom:c.zoom});}
function fit(width,height,bounds,aspect){var full=box(width,height,null,aspect),w=Math.max(32,finite(bounds.width,32)),h=Math.max(32,finite(bounds.height,32)),z=Math.min(4,full.width/(w*1.6),full.height/(h*1.6));return camera(width,height,{x:bounds.x+bounds.width/2,y:bounds.y+bounds.height/2,zoom:z});}
function zoomAt(width,height,c,factor,point){c=camera(width,height,c);var next=zoom(width,height,c,factor),ratio=c.zoom/next.zoom;next.x=point.x+(c.x-point.x)*ratio;next.y=point.y+(c.y-point.y)*ratio;return next;}
exports.fit=fit;exports.zoomAt=zoomAt;
exports.camera=camera;exports.box=box;exports.reset=reset;exports.zoom=zoom;exports.pan=pan;
})();
"},"$:/plugins/huwiki/cutout/model.js":{"title":"$:/plugins/huwiki/cutout/model.js","type":"application/javascript","module-type":"library","text":"var coUi=require("$:/plugins/huwiki/cutout/i18n.js");
/*\
title: $:/plugins/huwiki/cutout/model.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
function clone(x){return JSON.parse(JSON.stringify(x));}
function id(prefix){return (prefix||'id')+'-'+(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function read(wiki,title){try{return JSON.parse(wiki.getTiddlerText(title,'null'));}catch(e){return null;}}
function resolve(wiki,uid,title){var found=null;if(uid)(wiki.eachShadowPlusTiddlers||wiki.each).call(wiki,function(t,n){if(t.fields['cutout-id']===uid)found=n;});return found||title;}
function write(wiki,title,data,kind){var old=wiki.getTiddler(title);data.id=data.id||old&&old.fields['cutout-id']||id(kind);data.kind=kind||data.kind||'animation';wiki.addTiddler(new $tw.Tiddler(old,{title:title,type:'application/json','cutout-id':data.id,'cutout-kind':data.kind,'cutout-project':'yes',text:JSON.stringify(data,null,2)},wiki.getModificationFields()));return data.id;}
function list(wiki,kind){var entries=Object.create(null);(wiki.eachShadowPlusTiddlers||wiki.each).call(wiki,function(t,title){if(t.fields['cutout-kind']===kind)entries[t.fields['cutout-id']||title]={title:title,id:t.fields['cutout-id'],name:coUi.contentName(title,(read(wiki,title)||{}).name||title,wiki)};});return Object.keys(entries).map(function(id){return entries[id];}).sort(function(a,b){return a.name.localeCompare(b.name,'da');});}
function instantiate(puppet){var prefix=id('instance'),parts=clone(puppet.parts||[]),map={};parts.forEach(function(p){map[p.id]=prefix+'/'+p.id;});parts.forEach(function(p){var source=p.id;p.sourcePartId=source;p.id=map[source];p.parent=map[p.parent]||'';p.instanceId=prefix;p.puppetId=puppet.id;p.keys=(p.keys&&p.keys.length?[clone(p.keys[0])]:[{t:0,x:0,y:0,r:0,sx:1,sy:1,opacity:1}]);p.keys[0].t=0;});return parts;}
function copyProject(data){var c=clone(data);c.id=id(c.kind);c.name=(c.name||coUi.t('Projekt'))+coUi.t(' – kopi');return c;}
function validate(data){var errors=[],parts=data.parts||[],ids={};parts.forEach(function(p){if(!p.id||ids[p.id])errors.push(coUi.t('Del-ID mangler eller er gentaget'));ids[p.id]=p;});parts.forEach(function(p){var cursor=p,seen={};while(cursor&&cursor.parent){if(seen[cursor.id]){errors.push(coUi.t('Cirkulært hierarki'));break;}seen[cursor.id]=true;if(!ids[cursor.parent]){errors.push(coUi.t('Overdelen findes ikke'));break;}cursor=ids[cursor.parent];}});if(data.camera){var seenTimes={};if(!Array.isArray(data.camera.keys))errors.push(coUi.t('Kameraets nøglebilleder mangler'));else data.camera.keys.forEach(function(k){if(!Number.isFinite(k.t)||k.t<0||seenTimes[k.t])errors.push(coUi.t('Kameratid er ugyldig eller gentaget'));seenTimes[k.t]=true;if(!Number.isFinite(k.x)||!Number.isFinite(k.y)||!Number.isFinite(k.zoom)||k.zoom<.25||k.zoom>16)errors.push(coUi.t('Kameraets udsnit er ugyldigt'));});}return errors;}
function updateInstance(scene,instanceId,puppet){var old=scene.parts.filter(function(p){return p.instanceId===instanceId;}),newParts=instantiate(puppet),ids={};newParts.forEach(function(p){var prev=old.find(function(q){return q.sourcePartId===p.sourcePartId;});if(prev){ids[p.id]=prev.id;p.keys=clone(prev.keys);}else ids[p.id]=p.id;});newParts.forEach(function(p){p.id=ids[p.id];p.parent=ids[p.parent]||'';p.instanceId=instanceId;});scene.parts=scene.parts.filter(function(p){return p.instanceId!==instanceId;}).concat(newParts);}
function dependencies(wiki,title,data){var out=[],seen={};function add(name,obj){if(!name||seen[name])return;seen[name]=true;var t=wiki.getTiddler(name);if(!obj&&!t)return;var fields=t?Object.assign({},t.fields):{title:name,type:'application/json'};if(obj){fields.text=JSON.stringify(obj);fields['cutout-id']=obj.id;fields['cutout-kind']=obj.kind;}out.push(fields);var d=obj||read(wiki,name);if(!d)return;(d.parts||[]).forEach(function(p){if(p.type==='animation')add(resolve(wiki,p.animationId,p.animation));if(p.asset||p.assetId)add(resolve(wiki,p.assetId,p.asset));(p.variants||[]).forEach(function(v){add(resolve(wiki,v.assetId,v.asset));add(resolve(wiki,v.sourceId,v.source));});});(d.scenes||[]).forEach(function(c){add(resolve(wiki,c.sourceId,c.source||c.animation||c.theatre));});}add(title,data);return out;}
exports.dependencies=dependencies;
// SVG paints siblings in document order. Reorder only peers: keep hierarchy,
// stable IDs and keyframes intact. Theatre foreground roots form their own stack.
function layerPeers(data,p){return (data.parts||[]).filter(function(q){return (q.parent||'')===(p.parent||'')&&((p.parent||!data.scenes)||!!q.foreground===!!p.foreground);});}
function moveLayer(data,p,where){var peers=layerPeers(data,p),index=peers.indexOf(p),next=where==='front'?peers.length-1:where==='back'?0:index+(where==='forward'?1:-1);next=Math.max(0,Math.min(peers.length-1,next));if(index<0||index===next)return false;var target=peers[next],parts=data.parts;parts.splice(parts.indexOf(p),1);parts.splice(parts.indexOf(target)+(next>index?1:0),0,p);return true;}
exports.layerPeers=layerPeers;exports.moveLayer=moveLayer;
exports.clone=clone;exports.id=id;exports.read=read;exports.resolve=resolve;exports.write=write;exports.list=list;exports.instantiate=instantiate;exports.copyProject=copyProject;exports.validate=validate;exports.updateInstance=updateInstance;
})();
"},"$:/plugins/huwiki/cutout/widgets/studio.js":{"title":"$:/plugins/huwiki/cutout/widgets/studio.js","type":"application/javascript","module-type":"widget","text":"var coUi=require("$:/plugins/huwiki/cutout/i18n.js");
/*\
title: $:/plugins/huwiki/cutout/widgets/studio.js
type: application/javascript
module-type: widget
\*/
(function(){'use strict';
var Widget=require('$:/core/modules/widgets/widget.js').widget,E=require('$:/plugins/huwiki/cutout/engine.js'),M=require('$:/plugins/huwiki/cutout/model.js'),Clock=require('$:/plugins/huwiki/cutout/clock.js').Clock,V=require('$:/plugins/huwiki/cutout/viewport.js');
var names=coUi.names({puppet:'Dukkeværksted',animation:'Animationsstudie',scene:'Scenestudie',theatre:'Teaterstudie'});
function Studio(p,o){this.initialise(p,o);}Studio.prototype=new Widget();
Studio.prototype.render=function(parent,next){this.parentDomNode=parent;this.computeAttributes();this.mode=this.getAttribute('mode',this.defaultMode||'puppet');this.title=this.getAttribute('tiddler','');this.time=0;this.camera=null;this.panMode=false;this.selected=null;this.data=null;this.dirty=false;var h=this.document.createElement('section');h.className='co-studio';h.tabIndex=0;this.host=h;parent.insertBefore(h,next);this.domNodes.push(h);if(this.title)this.load(this.title);if(this.data){var initial=this.getAttribute('part','');if((this.mode==='theatre'&&initial==='@camera')||(this.data.parts||[]).concat(this.data.scenes||[]).some(function(p){return p.id===initial;}))this.selected=initial;this.time=this.mode==='puppet'?0:E.clamp(E.finite(this.getAttribute('time','0'),0),0,this.data.duration);}coUi.restore(this,"studio");coUi.remember(this,"studio");this.ui();if(this._coResume&&this.clock){this.clock.seek(this.time);this.clock.play();}};
Studio.prototype.node=function(tag,text,cls,parent){var e=this.document.createElement(tag);if(text!==undefined)e.textContent=coUi.contentName(this.title,text,this.wiki);if(cls)e.className=cls;if(parent)parent.appendChild(e);return e;};
Studio.prototype.button=function(parent,text,fn){var b=this.node('button',text,'',parent);b.type='button';b.onclick=fn;return b;};
Studio.prototype.message=function(s){if(this.status)this.status.textContent=s;};
Studio.prototype.draft=function(){if(this.dirty&&this.data&&this.title)this.wiki.addTiddler(new $tw.Tiddler({title:'$:/CutOut/Drafts/'+this.title,type:'application/json',text:JSON.stringify(this.data)}));};
Studio.prototype.mark=function(){this.dirty=true;this.draft();this.message(coUi.t('Ændringer gemt som kladde · Gem projekt for at anvende'));};
Studio.prototype.load=function(title){this.stop();this.draft();this.title=title;this.data=M.read(this.wiki,'$:/CutOut/Drafts/'+title)||M.read(this.wiki,title);this.dirty=!!this.wiki.getTiddler('$:/CutOut/Drafts/'+title);this.camera=null;this.cameraPreview=false;var items=this.data&&(this.mode==='theatre'?this.data.scenes:this.data.parts)||[];this.selected=items[0]&&items[0].id;this.time=0;};
Studio.prototype.save=function(){if(!this.data)return false;var errors=M.validate(this.data);if(errors.length){this.message(errors.join(' · '));return false;}M.write(this.wiki,this.title,this.data,this.mode);this.wiki.deleteTiddler('$:/CutOut/Drafts/'+this.title);this.dirty=false;this.message(this.wiki.getTiddlerText('$:/Wiki/CurrentWikiId','')?coUi.t('Projekt opdateret · HUWiki synkroniserer med Drev'):coUi.t('Projekt gemt · Gem også wikien på disk'));return true;};
